// Output-code gains, separate from WLED's gamma, Kelvin and brightness transforms.
namespace BusRgbCalibration {
constexpr uint32_t CHANNEL_MASK = 0xFFU;
constexpr uint32_t GAINS_MASK = 0x00FFFFFFU;
constexpr uint32_t GPIO_MASK = 0x7FU;
constexpr unsigned GREEN_SHIFT = 8;
constexpr unsigned BLUE_SHIFT = 16;
constexpr unsigned GPIO_SHIFT = 24;
constexpr uint32_t ENABLED_MASK = 0x80000000U;
constexpr int UNSET_GPIO = 127;
constexpr int UNITY_GAIN = 100;
constexpr int MAX_GAIN = 200;
constexpr uint32_t UNITY_GAINS = 0x00646464U;

// Call only after validation: one word publishes all gains and the output selector together.
constexpr uint32_t pack(int dataGpio, bool isEnabled, int redGain, int greenGain, int blueGain) {
  return uint32_t(redGain) | (uint32_t(greenGain) << GREEN_SHIFT) | (uint32_t(blueGain) << BLUE_SHIFT)
       | (uint32_t(dataGpio < 0 ? UNSET_GPIO : dataGpio) << GPIO_SHIFT) | (isEnabled ? ENABLED_MASK : 0U);
}

constexpr int gpio(uint32_t state) {
  return ((state >> GPIO_SHIFT) & GPIO_MASK) == UNSET_GPIO ? -1 : int((state >> GPIO_SHIFT) & GPIO_MASK);
}
constexpr bool enabled(uint32_t state) { return (state & ENABLED_MASK) != 0; }
constexpr uint8_t red(uint32_t state) { return state & CHANNEL_MASK; }
constexpr uint8_t green(uint32_t state) { return (state >> GREEN_SHIFT) & CHANNEL_MASK; }
constexpr uint8_t blue(uint32_t state) { return (state >> BLUE_SHIFT) & CHANNEL_MASK; }

// Platform-specific GPIO capability checking belongs to the caller, before narrowing.
constexpr bool valid(int dataGpio, int redGain, int greenGain, int blueGain) {
  return dataGpio >= -1 && dataGpio < UNSET_GPIO
      && redGain >= 0 && redGain <= MAX_GAIN && greenGain >= 0 && greenGain <= MAX_GAIN
      && blueGain >= 0 && blueGain <= MAX_GAIN;
}

constexpr uint32_t DEFAULT_STATE = pack(-1, false, UNITY_GAIN, UNITY_GAIN, UNITY_GAIN);

// Round half up and saturate independently; a gain boost never rescales other channels.
inline __attribute__((always_inline)) uint8_t scale(uint8_t channel, uint8_t gain) {
  const uint32_t scaled = (uint32_t(channel) * gain + UNITY_GAIN / 2) / UNITY_GAIN;
  return scaled > 255U ? 255U : scaled;
}

// Transform a local WRGB color only. Never feed calibrated transport readback into this again.
inline __attribute__((always_inline)) uint32_t apply(uint32_t color, uint32_t state, uint8_t dataGpio) {
  if (!enabled(state) || gpio(state) != dataGpio || (state & GAINS_MASK) == UNITY_GAINS) return color;
  return (color & 0xFF000000U)
       | (uint32_t(scale(uint8_t(color >> 16), red(state))) << 16)
       | (uint32_t(scale(uint8_t(color >> 8), green(state))) << 8)
       | scale(uint8_t(color), blue(state));
}
} // namespace BusRgbCalibration
